// State machine for tumbler/dryer
// States: idle → running → finishing → done
// 'finishing' = low-power drum-tumbling after program ends (keeps clothes fluffy)

const RUNNING_W   = parseFloat(env.get('TUMBLER_RUNNING_W')  || '300')
const FINISHING_W = parseFloat(env.get('TUMBLER_FINISHING_W') || '50')
const IDLE_W      = parseFloat(env.get('TUMBLER_IDLE_W')      || '5')
const FINISHING_TIMEOUT_MS = parseFloat(env.get('TUMBLER_FINISHING_MIN') || '12') * 60000
const PANELS = (env.get('APPLIANCE_PANELS') || 'kitchen').split(',').map(s => s.trim())

const power = parseFloat(msg.payload) || 0
const now = Date.now()

let state      = flow.get('tumbler_state')      || 'idle'
let since      = flow.get('tumbler_since')      || now
let finishTime = flow.get('tumbler_finishTime') || null

let newState = state

if (power >= RUNNING_W) {
    // High power = definitely running
    if (state !== 'running') {
        newState = 'running'
        since = now
        finishTime = null
    }
} else if (power <= IDLE_W) {
    if (state === 'finishing') {
        // Was in finishing — check if timeout expired
        if (finishTime && (now - finishTime) >= FINISHING_TIMEOUT_MS) {
            newState = 'done'
            since = now
        }
        // else: stay in finishing, timeout not yet reached
    } else if (state === 'running') {
        // Power dropped from running straight to idle (fast programs)
        newState = 'finishing'
        since = now
        finishTime = now
    }
    // idle stays idle
} else if (power > IDLE_W && power < RUNNING_W) {
    // Medium power = finishing phase (drum tumbling without heat)
    if (state === 'running') {
        newState = 'finishing'
        since = now
        finishTime = now
    } else if (state === 'finishing') {
        // Still in finishing — reset timer if power went back up slightly
        if (power > FINISHING_W) finishTime = now
    }
}

flow.set('tumbler_state', newState)
flow.set('tumbler_since', since)
flow.set('tumbler_finishTime', finishTime)

// Only publish when state changes
if (newState === state && newState !== 'finishing') return null

msg.applianceId = 'tumbler'
msg.panels = PANELS
msg.panelIndex = 0
msg.appliancePayload = {
    state: newState,
    power: Math.round(power),
    since: new Date(since).toISOString()
}
return msg

const panels = msg.panels
const i = msg.panelIndex
if (i >= panels.length) return null
msg.topic = `dashboard/panels/${panels[i]}/appliances/${msg.applianceId}/state`
msg.payload = msg.appliancePayload
msg.qos = 1
msg.retain = true
msg.panelIndex = i + 1
if (i + 1 < panels.length) {
    node.send([msg, msg])
} else {
    node.send([msg, null])
}

const PANELS = (env.get('APPLIANCE_PANELS') || 'kitchen').split(',').map(s => s.trim())
const now = new Date().toISOString()

let raw = msg.payload
if (typeof raw === 'string') {
    try { raw = JSON.parse(raw) } catch { raw = { state: raw } }
}

const validStates = ['idle', 'running', 'finishing', 'done']
let state = 'idle'
if (raw && typeof raw === 'object') {
    const s = (raw.state || raw.status || '').toLowerCase()
    state = validStates.includes(s) ? s : 'idle'
} else if (typeof raw === 'string') {
    const s = raw.toLowerCase()
    state = validStates.includes(s) ? s : 'idle'
}

msg.applianceId = 'waschmaschine'
msg.panels = PANELS
msg.panelIndex = 0
msg.appliancePayload = {
    state: state,
    power: (raw && typeof raw === 'object' && raw.power != null) ? raw.power : null,
    since: (raw && typeof raw === 'object' && raw.since) ? raw.since : now
}
return msg
